5: import {
6:   normalizeGeoName,
7:   hasSpecificNameOverlap,
8: } from './nominatim-match.util';
9: 
10: /**
11:  * Pure, provider-neutral, no-network helper that builds the local identity
12:  * evidence factors for a transient EntityCandidate. Used by both
13:  * ExperienceProposalResolverService and AreaRouteAnchorResolverService so
14:  * the same evidence-construction logic is never duplicated.
15:  *
16:  * This only produces local (non-network) evidence. External corroboration
17:  * (Wikidata identity match) is still collected separately by
18:  * IdentityEvidenceCollector.
19:  */
20: export function buildLocalIdentityEvidence(
21:   hint: { name: string },
22:   candidate: EntityCandidate,
23: ): IdentityEvidence[] {
24:   const evidence: IdentityEvidence[] = [];
25:   const nameMultiplicity = candidate.nameEvidenceMultiplicity;
26: 
27:   if (
28:     normalizeGeoName(candidate.canonicalName ?? '') ===
29:     normalizeGeoName(hint.name)
30:   ) {
31:     evidence.push({
32:       type: 'EXACT_NAME',
33:       identityMultiplicity: nameMultiplicity.exactName,
34:     });
35:   }
36: 
37:   if (candidate.addressConfirmed) {
38:     evidence.push({ type: 'ADDRESS_MATCH' });
39:   }
40: 
41:   // DECLARED_ALIAS_MATCH: aliases come from the specific candidate's own
42:   // OSM tags (name:xx, alt_name, wikipedia). If the candidate has at least
43:   // one matching alias, that is a direct declaration by the same real record
44:   // -- not a pool-level ambiguity. Use the candidate's declaredAlias multiplicity.
45:   const hasMatchingAlias = (candidate.nameAliasCandidates ?? []).some((alias) =>
46:     hasSpecificNameOverlap(
47:       normalizeGeoName(hint.name),
48:       normalizeGeoName(alias),
49:       { requireAllTokens: true },
50:     ),
51:   );
52:   if (hasMatchingAlias) {
53:     evidence.push({
54:       type: 'DECLARED_ALIAS_MATCH',
55:       identityMultiplicity: nameMultiplicity.declaredAlias,
56:     });
57:   }
58: 
59:   return evidence;
60: }

